package dev.veltraph.client.builder;
import dev.veltraph.client.config.*;
import dev.veltraph.client.gui.MenuSnapshot;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Adapted native leg path: the same strategy, policy, authority and receive journal used by the registered port. */
class Source95PaidBoundaryTest {
 private static final String CONTRACT="{\"WHEAT\":{\"productName\":\"Seeds\",\"resourceComponents\":\"@vanilla\",\"menuTitles\":[\"Seeds\"],\"controls\":{\"instant\":\"Instant\",\"stack\":\"Stack\"},\"maxTotalCoins\":500,\"clickDelayMillis\":100,\"timeoutMillis\":30000}}";
 private final Source95AcquisitionBinding binding=Source95AcquisitionBinding.decode(CONTRACT,BuilderCropType.WHEAT);
 private MapConfigService config(){var c=new MapConfigService();c.set(BuilderConfig.BUILDER_BUY_RESOURCES,true);c.set(BuilderConfig.BUILDER_CROP_TYPE,BuilderCropType.WHEAT);c.set(GeneratedBuilderConfig.IRONMAN_MODE,false);c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT);return c;}
 private Source95AcquisitionAuthority.Scope scope(){return new Source95AcquisitionAuthority.Scope(new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),4,1);}
 private Source95ChatReceipts.Scope chat(Source95AcquisitionAuthority.Scope s){return new Source95ChatReceipts.Scope(s.player(),s.world(),s.connection(),s.menu(),s.screen(),s.menuId());}
 private MenuSnapshot menu(int revision){return new MenuSnapshot(4,"Seeds",List.of(new MenuSnapshot.Slot(13,"Stack",List.of("Item: Seeds","Amount: 64x","Price: 192 Coins"),false,"minecraft:paper",1,false)),revision);}
 private Source95BazaarLeg dispatch(Source95AcquisitionAuthority a,Source95AcquisitionPolicy policy,ConfigService c,Source95AcquisitionAuthority.Scope s,int before,long packetFloor,long now){assertTrue(policy.validate(c,a));assertTrue(a.validateOwnedBoundary(s.player(),s.world(),s.connection(),s.owner(),s.menu(),s.screen(),s.menuId(),false,false));var leg=new Source95BazaarLeg(Source95PurchaseChooser.choose(a.remaining(),true,false,64,20),before,true);assertEquals(Source95BazaarLeg.Kind.CLICK,leg.tick(binding,menu(1),false,before,a.remainingCap()).kind());assertEquals(64,leg.quantity());assertTrue(a.issueLeg(binding,s,leg.quantity(),leg.quotedCost(),before,packetFloor,now));return leg;}
 private void nativeMessage(Object token,Source95AcquisitionAuthority.Scope s,long floor,Source95BazaarLeg leg){Source95ChatReceipts.received(s.connection(),chat(s),"[Bazaar] Bought 64x Seeds for 192 coins!",false);for(var r:Source95ChatReceipts.after(s.connection(),token,floor,s))leg.message(r,binding);}
 @Test void twoIdenticalStackMessagesDistinctEventsSameMenuCompleteOne128IntentEvenWith1000Owned(){var c=config();var a=new Source95AcquisitionAuthority();var policy=new Source95AcquisitionPolicy(binding);var s=scope();Object token=new Object();Source95ChatReceipts.attach(s.connection(),token);try{var intent=a.intent();var ids=new HashSet<UUID>();long previousEvent=-1;for(int legNo=0;legNo<2;legNo++){int before=1000+64*legNo;long floor=Source95ChatReceipts.floor();var leg=dispatch(a,policy,c,s,before,10+legNo,legNo*2);nativeMessage(token,s,floor,leg);assertTrue(policy.validate(c,a));leg.tick(binding,menu(2),false,before+64,a.remainingCap());assertEquals(Source95BazaarLeg.State.COMPLETE,leg.state());assertTrue(leg.messageEvent()>previousEvent);previousEvent=leg.messageEvent();assertTrue(a.acknowledgeLeg(s,before+64,64,leg.charged(),true,11+legNo,true,true,legNo*2+1));assertTrue(Source95ChatReceipts.consume(s.connection(),token,leg.messageEvent()));assertTrue(ids.add(a.legReceiptId()));assertEquals(intent,a.intent());}assertEquals(128,a.acquired());assertEquals(384,a.spent());assertEquals(2,a.legs());assertEquals(Source95AcquisitionAuthority.State.CONFIRMED,a.state());}finally{Source95ChatReceipts.detach(s.connection(),token);}}
 @Test void revokedPaidStrategyCanObserveLateMessageAndDeltaButNeverAuthorizeAckOrSecondClick(){for(boolean partial:List.of(false,true))for(int key=0;key<5;key++){var c=config();var a=new Source95AcquisitionAuthority();var policy=new Source95AcquisitionPolicy(binding);var s=scope();Object token=new Object();Source95ChatReceipts.attach(s.connection(),token);try{int before=127;if(partial){long firstFloor=Source95ChatReceipts.floor();var first=dispatch(a,policy,c,s,before,10,0);nativeMessage(token,s,firstFloor,first);first.tick(binding,menu(2),false,191,500);assertTrue(a.acknowledgeLeg(s,191,64,first.charged(),true,11,true,true,1));assertTrue(Source95ChatReceipts.consume(s.connection(),token,first.messageEvent()));before=191;}long floor=Source95ChatReceipts.floor();var leg=dispatch(a,policy,c,s,before,partial?11:10,2);switch(key){case 0->c.set(BuilderConfig.BUILDER_BUY_RESOURCES,false);case 1->c.set(GeneratedBuilderConfig.IRONMAN_MODE,true);case 2->c.set(BuilderConfig.BUILDER_CROP_TYPE,BuilderCropType.CARROT);case 3->c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT.replace("500","100"));case 4->c.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT.replace("Stack","Other"));default->throw new AssertionError();}assertFalse(policy.validate(c,a));nativeMessage(token,s,floor,leg);leg.tick(binding,menu(2),false,before+64,500);assertEquals(Source95BazaarLeg.State.COMPLETE,leg.state());assertFalse(policy.validate(c,a));assertFalse(a.acknowledgeLeg(s,before+64,64,leg.charged(),true,12,true,true,3));assertFalse(a.issueLeg(binding,s,64,192,before+64,12,4));assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,a.state());assertEquals(partial?64:0,a.acquired());assertEquals(partial?192:0,a.spent());assertTrue(a.unknownOutcome().isPresent());}finally{Source95ChatReceipts.detach(s.connection(),token);}}}
 @Test void consumedFirstReceiptPlusFreshSameItemPickupCannotSupplySecondReceipt(){var c=config();var a=new Source95AcquisitionAuthority();var policy=new Source95AcquisitionPolicy(binding);var s=scope();Object token=new Object();Source95ChatReceipts.attach(s.connection(),token);try{long floor=Source95ChatReceipts.floor();var first=dispatch(a,policy,c,s,127,10,0);nativeMessage(token,s,floor,first);first.tick(binding,menu(2),false,191,500);assertTrue(a.acknowledgeLeg(s,191,64,192,true,11,true,true,1));assertTrue(Source95ChatReceipts.consume(s.connection(),token,first.messageEvent()));long next=Source95ChatReceipts.floor();var second=dispatch(a,policy,c,s,191,11,2);assertTrue(Source95ChatReceipts.after(s.connection(),token,next,s).isEmpty());second.tick(binding,menu(2),false,255,308);assertEquals(Source95BazaarLeg.State.ACK,second.state());assertEquals(64,a.acquired());assertEquals(Source95AcquisitionAuthority.State.ISSUED,a.state());a.timedOut(30002);assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,a.state());assertFalse(a.issueLeg(binding,s,64,192,255,12,30003));}finally{Source95ChatReceipts.detach(s.connection(),token);}}
}
